  void detectRouter(){if(probing)return;probing=true;status.setText("جارٍ اكتشاف الراوتر...");new Thread(()->{LinkedHashSet<String> ips=new LinkedHashSet<>(Arrays.asList(baseUrl,"http://192.168.8.1","http://192.168.1.1","http://192.168.0.1","http://192.168.100.1","http://10.0.0.1"));String found=null;for(String u:ips){try{String p=get(u+"/",1500);if(p!=null&&!p.isEmpty()){found=u;break;}}catch(Exception ignored){}}String f=found;runOnUiThread(()->{probing=false;if(f==null){status.setText("لم يتم العثور على راوتر");new AlertDialog.Builder(this).setTitle("لا يوجد راوتر").setMessage("اتصل بـ Wi-Fi ثم أعد المحاولة، أو استخدم اختبار السرعة من بيانات الهاتف.").setPositiveButton("بيانات الهاتف",(d,w)->{phoneMode=true;authenticated=true;vendor="بيانات الهاتف";driver="Android Mobile";showPage(0);}).setNegativeButton("إعادة",(d,w)->detectRouter()).show();return;}baseUrl=f;prefs.edit().putString("baseUrl",f).apply();setV("gateway",f);web.loadUrl(f+"/");h.postDelayed(this::loginDialog,350);});}).start();}
  String get(String u,int timeout)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(u).openConnection();c.setConnectTimeout(timeout);c.setReadTimeout(timeout);InputStream in=c.getInputStream();ByteArrayOutputStream o=new ByteArrayOutputStream();byte[] b=new byte[4096];int n,total=0;while((n=in.read(b))>0&&total<150000){o.write(b,0,n);total+=n;}in.close();return o.toString("UTF-8");}
  void loginDialog(){if(phoneMode)return;LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(20),dp(5),dp(20),0);EditText user=new EditText(this);user.setText("admin");user.setEnabled(false);box.addView(user,new LinearLayout.LayoutParams(-1,dp(52)));EditText pass=new EditText(this);pass.setText(password);pass.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);box.addView(pass,new LinearLayout.LayoutParams(-1,dp(52)));AlertDialog d=new AlertDialog.Builder(this).setTitle("دخول الراوتر").setMessage("اسم المستخدم: admin").setView(box).setPositiveButton("اتصال",null).create();d.setCancelable(false);d.setOnShowListener(x->d.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{password=pass.getText().toString().trim();if(password.isEmpty())password="admin";prefs.edit().putString("routerPassword",password).apply();authenticated=false;status.setText("جارٍ تسجيل الدخول...");web.loadUrl(baseUrl+"/");h.postDelayed(()->verify(d),1800);}));d.show();}
  void autoLogin(){if(phoneMode)return;String p=password.replace("\\","\\\\").replace("'","\\'");String js="javascript:(()=>{try{let u=document.querySelector('input[name=username],#username,input[type=text]');let pw=document.querySelector('input[name=password],#password,input[type=password]');if(!pw)return 'noform';if(u)u.value='admin';pw.value='"+p+"';let b=document.querySelector('#login_btn,#loginbutton,button[type=submit],input[type=submit],.login_button,.btn_login');if(b){b.click();return 'clicked'}return 'nobutton'}catch(e){return 'err'}})()";web.evaluateJavascript(js,null);}
  void verify(AlertDialog d){String js="javascript:(async()=>{const g=async u=>{try{return await (await fetch(u,{credentials:'same-origin',cache:'no-store'})).text()}catch(e){return 'NETERR'}};let a=await g('/api/device/information');let b=await g('/api/device/signal');let c=await g('/api/net/net-mode');let e=await g('/api/user/state-login');let s=await g('/api/monitoring/status');return a+'|||'+b+'|||'+c+'|||'+e+'|||'+s})()";web.evaluateJavascript(js,val->{String out=decode(val),low=out.toLowerCase(Locale.US);boolean ok=out.contains("<DeviceName>")||out.contains("<SerialNumber>")||low.contains("<rsrp>")||out.contains("<NetworkMode>")||low.contains("<username>admin</username>")||out.contains("<ConnectionStatus>");boolean denied=low.contains("100003")||low.contains("100002")||low.contains("unauthorized")||low.contains("not login");if(ok){authenticated=true;huawei=true;vendor="Huawei / HiLink";driver="HuaweiHiLink Deep";prefs.edit().putBoolean("huawei",true).apply();d.dismiss();status.setText("تم الدخول • Huawei HiLink Deep Driver");showPage(0);refreshAll();}else if(denied||low.contains("neterr")){Toast.makeText(this,"خطأ في رمز دخول الراوتر",Toast.LENGTH_LONG).show();status.setText("رمز الدخول غير صحيح أو الجلسة غير مفعلة");}else{Toast.makeText(this,"تعذر تأكيد دخول الإدارة",Toast.LENGTH_LONG).show();}});}
  String decode(String v){try{return new JSONArray("["+v+"]").getString(0);}catch(Exception e){return v==null?"":v.replace("\\n","\n").replace("\\\"","\"");}}
  void refreshAll(){if(phoneMode){setV("vendor","هاتف Android");setV("driver","Mobile Data");return;}if(!authenticated)return;setV("vendor",vendor);setV("driver",driver);setV("gateway",baseUrl);String js="javascript:(async()=>{const q=async(u,k)=>{try{let r=await fetch(u,{credentials:'same-origin',cache:'no-store'});let t=await r.text();Shahboun.data(k,t)}catch(e){Shahboun.data(k,'NETERR')}};await Promise.all([q('/api/device/signal','signal'),q('/api/monitoring/status','status'),q('/api/device/information','device'),q('/api/net/net-mode','net'),q('/api/wlan/host-list','hosts'),q('/api/monitoring/traffic-statistics','traffic'),q('/api/net/current-plmn','plmn')])})()";web.evaluateJavascript(js,null);}
  boolean err(String x){if(x==null)return true;String l=x.toLowerCase(Locale.US);return l.contains("<error>")||l.contains("100003")||l.contains("100002")||l.equals("neterr");}
  String tag(String x,String... ns){if(x==null)return "";for(String n:ns){Matcher m=Pattern.compile("<"+Pattern.quote(n)+">(.*?)</"+Pattern.quote(n)+">",Pattern.DOTALL|Pattern.CASE_INSENSITIVE).matcher(x);if(m.find())return m.group(1).trim();}return "";}
  double num(String s){try{return Double.parseDouble(s.replaceAll("[^0-9+\\-.]",""));}catch(Exception e){return 0;}}
  void parseSignal(String x){if(err(x))return;String rsrp=tag(x,"rsrp","Rsrp"),rsrq=tag(x,"rsrq","Rsrq"),sinr=tag(x,"sinr","Sinr"),band=tag(x,"band","Band"),pci=tag(x,"pci","Pci"),cell=tag(x,"cell_id","cellid","CellID"),ear=tag(x,"earfcn","dl_earfcn","EARFCN");if(!band.isEmpty())setV("band",band.toUpperCase().startsWith("B")?band:"B"+band);setV("rsrp",rsrp);setV("rsrq",rsrq);setV("sinr",sinr);setV("pci",pci);setV("cell",cell);setV("earfcn",ear);double si=num(sinr),rp=num(rsrp),rq=num(rsrq);if(!sinr.isEmpty())setV("quality",si>=15&&rp>=-90&&rq>=-10?"ممتاز":si>=8?"جيد":si>=3?"متوسط":"ضعيف / تداخل مرتفع");}
  void parseStatus(String x){if(err(x))return;String nt=tag(x,"CurrentNetworkTypeEx","CurrentNetworkType"),wan=tag(x,"WanIPAddress","WanIPAddr"),u=tag(x,"CurrentWifiUser","CurrentWifiUserNum");setV("networkType",("101".equals(nt)||"19".equals(nt))?"4G LTE":("20".equals(nt)||"1011".equals(nt))?"5G / NR":nt);setV("wanIp",wan);setV("wifiUsers",u);}
  void parseDevice(String x){if(err(x))return;setV("model",tag(x,"DeviceName","Classify","ProductFamily"));setV("firmware",tag(x,"SoftwareVersion"));setV("webui",tag(x,"WebUIVersion"));}
  void parseNet(String x){if(err(x))return;setV("netMode",tag(x,"NetworkMode"));setV("lteMask",tag(x,"LTEBand"));}
  void parseTraffic(String x){if(err(x))return;String cd=tag(x,"CurrentDownloadRate"),cu=tag(x,"CurrentUploadRate"),tds=tag(x,"TotalDownload"),tus=tag(x,"TotalUpload"),dur=tag(x,"CurrentConnectTime","CurrentConnectTimeSecond");long now=System.currentTimeMillis(),td=lng(tds),tu=lng(tus);double dl=-1,ul=-1;if(lng(cd)>0)dl=lng(cd)*8.0/1e6;if(lng(cu)>0)ul=lng(cu)*8.0/1e6;if(prevTs>0&&now>prevTs){double sec=(now-prevTs)/1000.0;if(dl<0&&prevDl>=0&&td>=prevDl)dl=(td-prevDl)*8/sec/1e6;if(ul<0&&prevUl>=0&&tu>=prevUl)ul=(tu-prevUl)*8/sec/1e6;}if(dl>=0)setV("liveDl",String.format(Locale.US,"%.2f Mbps",dl));if(ul>=0)setV("liveUl",String.format(Locale.US,"%.2f Mbps",ul));if(td>=0){setV("totalDl",bytes(td));prevDl=td;}if(tu>=0){setV("totalUl",bytes(tu));prevUl=tu;}if(!dur.isEmpty())setV("uptime",time(dur));prevTs=now;}
  long lng(String s){try{return Long.parseLong(s.trim());}catch(Exception e){return -1;}} String bytes(long b){if(b>=1073741824)return String.format(Locale.US,"%.2f GB",b/1073741824.0);if(b>=1048576)return String.format(Locale.US,"%.1f MB",b/1048576.0);return String.format(Locale.US,"%.0f KB",b/1024.0);} String time(String s){try{long n=Long.parseLong(s);return String.format(Locale.US,"%d:%02d:%02d",n/3600,(n%3600)/60,n%60);}catch(Exception e){return s;}}
  void bands(){if(!authenticated){loginDialog();return;}String[] n=new String[BANDS.length];for(int i=0;i<n.length;i++)n[i]=BANDS[i][0];new AlertDialog.Builder(this).setTitle("الترددات والدمج — تحكم مباشر").setItems(n,(d,w)->applyBand(BANDS[w][0],BANDS[w][1],BANDS[w][2])).setNegativeButton("إلغاء",null).show();}
  void applyBand(String label,String lte,String mode){String js="javascript:(async()=>{try{let s=await (await fetch('/api/webserver/SesTokInfo',{credentials:'same-origin'})).text();let t=(s.match(/<TokInfo>(.*?)<\\/TokInfo>/)||[])[1];if(!t)return 'NO_TOKEN';let body='<?xml version=\\\"1.0\\\" encoding=\\\"UTF-8\\\"?><request><NetworkMode>"+mode+"</NetworkMode><NetworkBand>3FFFFFFF</NetworkBand><LTEBand>"+lte+"</LTEBand></request>';let r=await fetch('/api/net/net-mode',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/xml','__RequestVerificationToken':t},body});return await r.text()}catch(e){return 'NETERR'}})()";web.evaluateJavascript(js,v->{String o=decode(v);if(o.contains("OK")){status.setText("تم تطبيق "+label);prefs.edit().putString("lastBand",label).apply();h.postDelayed(this::refreshAll,1800);}else Toast.makeText(this,"تعذر تطبيق التردد",Toast.LENGTH_LONG).show();});}
  void capabilities(){if(!authenticated){loginDialog();return;}String js="javascript:(async()=>{let eps=['/api/device/information','/api/device/signal','/api/monitoring/status','/api/monitoring/traffic-statistics','/api/net/net-mode','/api/net/current-plmn','/api/wlan/host-list','/api/wlan/basic-settings','/api/dialup/profiles','/api/sms/sms-count','/api/pin/status','/api/pin/simlock','/api/device/control'];let out=[];for(let e of eps){try{let r=await fetch(e,{credentials:'same-origin'});let t=await r.text();out.push(e+'='+((r.ok&&!t.includes('<error>'))?'OK':'LIMITED'))}catch(x){out.push(e+'=NO')}}return out.join('\\n')})()";web.evaluateJavascript(js,v->new AlertDialog.Builder(this).setTitle("API / Firmware Capability Matrix").setMessage(decode(v)).setPositiveButton("حسنًا",null).show());}
  void simCenter(){if(!authenticated){loginDialog();return;}String js="javascript:(async()=>{const g=async u=>{try{return await (await fetch(u,{credentials:'same-origin'})).text()}catch(e){return ''}};return (await g('/api/pin/status'))+'|||'+(await g('/api/pin/simlock'))+'|||'+(await g('/api/net/current-plmn'))+'|||'+(await g('/api/device/information'))})()";web.evaluateJavascript(js,v->{String o=decode(v);String[] p=o.split("\\|\\|\\|",-1);String st=tag(p[0],"SimState"),lock=tag(p[1],"SimLockEnable"),rem=tag(p[1],"SimLockRemainTimes","pSimLockRemainTimes"),op=tag(p[2],"FullName","ShortName","Numeric"),fw=tag(p[3],"SoftwareVersion"),imei=tag(p[3],"Imei","IMEI");String msg="الحالة: "+("0".equals(lock)?"مفتوح لأي شبكة":"1".equals(lock)?"مقفول على شبكة":"غير معروف")+"\nSIM: "+st+"\nالمشغل: "+op+"\nمحاولات Unlock: "+rem+"\nIMEI: "+imei+"\nFirmware: "+fw;new AlertDialog.Builder(this).setTitle("SIM Unlock Center").setMessage(msg).setPositiveButton("حسنًا",null).show();});}
  void loadHosts(){if(!authenticated)return;web.evaluateJavascript("javascript:fetch('/api/wlan/host-list',{credentials:'same-origin'}).then(r=>r.text())",v->{String o=decode(v);Matcher m=Pattern.compile("<Host>(.*?)</Host>",Pattern.DOTALL).matcher(o);StringBuilder s=new StringBuilder();int n=0;while(m.find()){n++;String z=m.group(1);s.append(n).append(") ").append(tag(z,"HostName","ActualName","IpAddress")).append("\nIP: ").append(tag(z,"IpAddress","IPAddress")).append("\nMAC: ").append(tag(z,"MacAddress","MACAddress")).append("\n\n");}setV("hosts",String.valueOf(n));new AlertDialog.Builder(this).setTitle("الأجهزة المتصلة ("+n+")").setMessage(s.length()==0?"لا توجد بيانات":s.toString()).setPositiveButton("حسنًا",null).show();});}
