  void restart(){post("/api/device/control","<?xml version=\"1.0\" encoding=\"UTF-8\"?><request><Control>1</Control></request>");}
  void post(String path,String body){String b=body.replace("'","\\'");String js="javascript:(async()=>{try{let s=await (await fetch('/api/webserver/SesTokInfo',{credentials:'same-origin'})).text();let t=(s.match(/<TokInfo>(.*?)<\\/TokInfo>/)||[])[1];let r=await fetch('"+path+"',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/xml','__RequestVerificationToken':t},body:'"+b+"'});return await r.text()}catch(e){return 'NETERR'}})()";web.evaluateJavascript(js,v->Toast.makeText(this,decode(v),Toast.LENGTH_LONG).show());}
  void safeRestore(){String[] a={"استرجاع إعداد الشبكة الأصلي","إعادة تشغيل الراوتر","فتح Factory Reset الرسمي"};new AlertDialog.Builder(this).setTitle("الاسترجاع الآمن").setItems(a,(d,w)->{if(w==0)applyBand("الوضع الأصلي","20800800D5","00");else if(w==1)restart();else showRouter();}).setNegativeButton("إلغاء",null).show();}
  void speedTest(){status.setText("جارٍ اختبار السرعة...");new Thread(()->{try{List<Double> ps=new ArrayList<>();int fail=0;for(int i=0;i<5;i++){try{ps.add(latency());}catch(Exception e){fail++;}}double ping=avg(ps),jit=jitter(ps),dl=download(5000000),ul=upload(1000000),loss=fail*20.0;String ts=new SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.US).format(new Date());String band=cache.getOrDefault("band","—");String rec=ts+" | "+fmt(dl)+"↓ "+fmt(ul)+"↑ | Ping "+fmt(ping)+" | "+band;String old=prefs.getString("history","");double score=dl*2+num(cache.getOrDefault("sinr","0"))*1.5-ping*.25;double oldScore=Double.longBitsToDouble(prefs.getLong("bestScore",Double.doubleToLongBits(-9999)));SharedPreferences.Editor ed=prefs.edit().putString("history",rec+"\n"+old);if(score>oldScore&&!"—".equals(band))ed.putLong("bestScore",Double.doubleToLongBits(score)).putString("bestBand",band);ed.apply();runOnUiThread(()->{setV("dl",fmt(dl)+" Mbps");setV("ul",fmt(ul)+" Mbps");setV("ping",fmt(ping)+" ms");setV("jitter",fmt(jit)+" ms");setV("loss",fmt(loss)+"%");setV("bestBand",prefs.getString("bestBand","—"));status.setText("السرعة: "+fmt(dl)+"↓ / "+fmt(ul)+"↑ Mbps");});}catch(Exception e){runOnUiThread(()->status.setText("فشل اختبار السرعة: "+e.getMessage()));}}).start();}
  double latency()throws Exception{long a=System.nanoTime();HttpURLConnection c=(HttpURLConnection)new URL("https://speed.cloudflare.com/__down?bytes=1&x="+System.nanoTime()).openConnection();c.setConnectTimeout(5000);c.setReadTimeout(5000);InputStream in=c.getInputStream();in.read();in.close();return (System.nanoTime()-a)/1e6;}
  double download(int bytes)throws Exception{long a=System.nanoTime();HttpURLConnection c=(HttpURLConnection)new URL("https://speed.cloudflare.com/__down?bytes="+bytes+"&x="+System.nanoTime()).openConnection();c.setConnectTimeout(8000);c.setReadTimeout(20000);InputStream in=new BufferedInputStream(c.getInputStream());byte[] b=new byte[32768];long n=0;int z;while((z=in.read(b))>0)n+=z;in.close();return n*8.0/((System.nanoTime()-a)/1e9)/1e6;}
  double upload(int bytes)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL("https://speed.cloudflare.com/__up").openConnection();c.setDoOutput(true);c.setRequestMethod("POST");c.setConnectTimeout(8000);c.setReadTimeout(20000);c.setFixedLengthStreamingMode(bytes);c.setRequestProperty("Content-Type","application/octet-stream");long a=System.nanoTime();OutputStream o=c.getOutputStream();byte[] b=new byte[32768];int left=bytes;while(left>0){int n=Math.min(left,b.length);o.write(b,0,n);left-=n;}o.close();InputStream in=c.getInputStream();while(in.read(b)>0){}in.close();return bytes*8.0/((System.nanoTime()-a)/1e9)/1e6;}
  double avg(List<Double>a){double s=0;for(double x:a)s+=x;return a.isEmpty()?0:s/a.size();} double jitter(List<Double>a){if(a.size()<2)return 0;double s=0;for(int i=1;i<a.size();i++)s+=Math.abs(a.get(i)-a.get(i-1));return s/(a.size()-1);} String fmt(double x){return String.format(Locale.US,"%.1f",x);}
