  void pinBest(){String b=prefs.getString("bestBand","");if(b.isEmpty()){Toast.makeText(this,"اختبر أكثر من تردد أولًا",Toast.LENGTH_LONG).show();return;}for(String[] x:BANDS)if(x[0].equalsIgnoreCase(b)||("B"+x[0]).equalsIgnoreCase(b)){applyBand("أفضل تردد "+b,x[1],x[2]);return;}new AlertDialog.Builder(this).setTitle("أفضل تردد").setMessage("أفضل نتيجة: "+b+". افتح مدير الترددات لتثبيته يدويًا.").setPositiveButton("الترددات",(d,w)->bands()).show();}
